from auto_config.generator.enb.managed_objects.managed_object import ManagedObject


class EthsvcParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):

        if not self.is_mo_ecpri:
            self.set_parameter('utilMeasSampInt', '15sec')
        elif (execution_config['hardware_platform'] == 'CUS2' or execution_config['hardware_platform'] == 'CUS3') \
                and 'smods' in self.enb_ent_config \
                and (self.enb_ent_config['smods']['1'].get('prod_code_planned') == "476147A"  # ASOF:
                     or self.enb_ent_config['smods']['1'].get('prod_code_planned') == "475587A"  # ASOE:
                     or self.enb_ent_config['smods']['1'].get('prod_code_planned') == "476254A"  # ASOG:
                     or self.enb_ent_config['smods']['1'].get('prod_code_planned') == "476255A"):  # ASOH:
            self.set_parameter('utilMeasSampInt', '15sec')
